source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && cd /root/autodl-tmp/pacs && python3 -c "
import json

# n=50 bf16 results - check mean vs median discrepancy
for name in ['profiling_output_bf16_ds_rand_s015', 'profiling_output_bf16_ds_imp_s015',
             'profiling_output_bf16_qw_rand_s015', 'profiling_output_bf16_qw_imp_s015']:
    try:
        with open(f'{name}/profiling_results.json') as f:
            d = json.load(f)
        ii = d['interaction_index']
        for phase in ['low_sparsity', 'high_sparsity']:
            for sp in ii.get(phase, {}):
                e = ii[phase][sp]
                print(f'{name.replace(\"profiling_output_bf16_\",\"\")} {phase} {sp}: mean={e[\"mean\"]:.4f}, median={e[\"median\"]:.4f}, skew={e.get(\"skewness\",\"N/A\")}, outliers={e.get(\"outlier_count\",\"N/A\")}')
    except FileNotFoundError:
        print(f'{name}: NOT FOUND')
"
